recipes.code:
{
  "inputs": [
    {
      "id": "algenta-api-key",
      "type": "promptString",
      "description": "Your Algenta API key. Create one in the Algenta dashboard or authenticate with `algenta login`.",
      "password": true
    }
  ],
  "servers": {
    "algenta": {
      "type": "stdio",
      "command": "uvx",
      "args": [
        "algenta-mcp@1.0.4"
      ],
      "env": {
        "ALGENTA_API_KEY": "${input:algenta-api-key}",
        "ALGENTA_BASE_URL": "https://api.algenta.ai"
      }
    }
  }
}
